import math

def v2(n):
    """Computes the exponent of 2 in the prime factorization of n."""
    if n == 0:
        return float('inf')
    count = 0
    while n > 0 and n % 2 == 0:
        count += 1
        n //= 2
    return count

def f(n):
    """Computes f(n) = n / 2^m where m = v_2(n)."""
    if n <= 0:
        raise ValueError("n must be positive")
    m = v2(n)
    return n // (2**m)

def check_condition(u, v):
    """Checks if the condition holds for given u and v."""
    if v <= 0 or u <= 0:
        return False

    for k in range(v):
        n_old = u + k
        n_new = u + v + k

        diff = f(n_new) - f(n_old)

        if diff % 4 != 0:
            return False
    return True

